using System;

namespace Enterprise.Accounting.Services
{
    public interface IAssetDepreciationService
    {
        decimal CalculateDepreciation(decimal cost, decimal currentValue);
    }

    public class AssetDepreciationService : IAssetDepreciationService
    {
        private const decimal DepreciationRate = 0.15m;
        private const decimal SalvageValue = 100.00m;

        // Clean business logic extracted via QCA Sequencer
        public decimal CalculateDepreciation(decimal cost, decimal currentValue)
        {
            if (cost <= 0) return 0;

            decimal calculatedDepreciation = cost * DepreciationRate;
            decimal newValue = currentValue - calculatedDepreciation;

            // Business rule: floor at salvage value
            if (newValue < SalvageValue)
            {
                calculatedDepreciation = currentValue - SalvageValue;
            }

            return calculatedDepreciation > 0 ? calculatedDepreciation : 0;
        }
    }
}

namespace Enterprise.Banking.Deposits;

public record DepositCalculationRequest(decimal Principal, decimal Rate, int Years, int Frequency);

public class DepositService
{
    // Мігрована логіка з COBOL DEPOSIT-CALC.CBL
    public decimal CalculateFutureValue(DepositCalculationRequest request)
    {
        if (request.Principal <= 0) return 0;

        // Математично точна реалізація формули складних відсотків
        double baseRate = 1 + (double)(request.Rate / request.Frequency);
        double exponent = request.Frequency * request.Years;
        decimal futureValue = request.Principal * (decimal)Math.Pow(baseRate, exponent);

        return Math.Round(futureValue, 2);
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

namespace Enterprise.SupplyChain.Inventory
{
    /// <summary>
    /// Modernized via QCA Framework.
    /// Pure Domain Service: Calculates FIFO Cost of Goods Sold without DB coupling.
    /// </summary>
    public class FifoValuationService
    {
        public void CalculateCogs(SaleLine sale, List<GoodsReceipt> receipts, InventoryItem masterItem)
        {
            decimal qtyToCost = sale.QtySold;
            decimal totalCogs = 0m;

            // Strictly ordered by date for FIFO compliance
            var availableReceipts = receipts
                .Where(r => r.ItemId == sale.ItemId && r.QtyAvailable > 0)
                .OrderBy(r => r.ReceiptDate);

            foreach (var receipt in availableReceipts)
            {
                if (qtyToCost <= 0) break;

                decimal consumedQty = Math.Min(receipt.QtyAvailable, qtyToCost);

                totalCogs += consumedQty * receipt.UnitPrice;
                receipt.QtyAvailable -= consumedQty;
                qtyToCost -= consumedQty;
            }

            // Architecture enhancement: Handling the missing legacy constraint
            if (qtyToCost > 0)
            {
                throw new InvalidOperationException($"Negative stock anomaly for Item {sale.ItemId}");
            }

            sale.Cogs = totalCogs;
            sale.IsProcessed = true;
            masterItem.TotalQty -= sale.QtySold;
        }
    }

    // Domain Models (Data Transfer Objects)
    public class SaleLine 
    { 
        public string ItemId { get; set; }
        public decimal QtySold { get; set; }
        public decimal Cogs { get; set; }
        public bool IsProcessed { get; set; }
    }

    public class GoodsReceipt 
    { 
        public string ItemId { get; set; }
        public DateTime ReceiptDate { get; set; }
        public decimal QtyAvailable { get; set; }
        public decimal UnitPrice { get; set; }
    }

    public class InventoryItem 
    { 
        public string ItemId { get; set; }
        public decimal TotalQty { get; set; }
    }
}

using Microsoft.AspNetCore.Mvc;

namespace Enterprise.Invoicing.Api
{
    [ApiController]
    [Route("api/v1/tax")]
    public class TaxController : ControllerBase
    {
        [HttpPost("calculate")]
        public IActionResult CalculateTax([FromBody] TaxRequestDto request)
        {
            // Business rules isolated from UI
            decimal taxRate = request.IsExport ? 0.0m : 0.20m;

            decimal taxableAmount = request.SubTotal - request.Discount;
            decimal finalTax = taxableAmount * taxRate;

            if (finalTax < 0) finalTax = 0;

            return Ok(new 
            { 
                Status = "Success", 
                CalculatedTax = finalTax 
            });
        }
    }

    public record TaxRequestDto(decimal SubTotal, decimal Discount, bool IsExport);
}

